@lru_cache(maxsize=512)
def pixmap(name: str, color: str, size: int = 18, ratio: float = 2.0) -> QPixmap:
    body = PATHS.get(name, PATHS['dashboard'])
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="{color}" '
           f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{body}</svg>')
    renderer = QSvgRenderer(QByteArray(svg.encode()))
    edge = int(size * ratio)
    image = QPixmap(edge, edge)
    image.fill(Qt.GlobalColor.transparent)
    painter = QPainter(image)
    renderer.render(painter, QRectF(0, 0, edge, edge))
    painter.end()
    image.setDevicePixelRatio(ratio)
    return image


def icon(name: str, color: str, selected: str | None = None, size: int = 18) -> QIcon:
    result = QIcon()
    result.addPixmap(pixmap(name, color, size), QIcon.Mode.Normal)
    result.addPixmap(pixmap(name, selected or color, size), QIcon.Mode.Selected)
    result.addPixmap(pixmap(name, selected or color, size), QIcon.Mode.Active)
    return result


